HEADER_SOURCE_OF_TRACE = 0x1  # 0-snapshot 1-GUI


def build_trace_file_name(board, cpu, trace_name, dt, node='', ext='txt'):
    # type (int, int, str, datetime, str, str) -> str
    trace_name = trace_name.replace(' ', '_')

    return '0x{:x}{:x}_{name}_{datetime}{node}.{ext}'.format(
        board,
        cpu,
        name=trace_name,
        datetime=dt.strftime('%Y%m%d_%H%M%S'),
        node=node,  # _master or _slave - for HSUPA L2 Taces
        ext=ext
    )


def build_trace_file_header(n_of_traces, idx, sw_version, start_datetime, end_datetime):
    # type: (int, int, str, datetime, datetime) -> str
    fmt = '%Y/%m/%d:%H:%M:%S.%f'
    start = start_datetime.strftime(fmt)[:-3]
    end = end_datetime.strftime(fmt)[:-3]

    header = ('{idx}, version:{version} TotalTrace:{total} Source:{source} TraceId:{trace} '
              'Start:{start} End:{end} SWVersion:{sw_version};\r\n')

    return header.format(
        idx=get_measurement_index(idx),
        version='taf.sbts.browser_server',
        total=n_of_traces,
        source=258,  # 257? or (HEADER_SOURCE_OF_TRACE << 8) + 1?
        trace=idx,
        start=start,
        end=end,
        sw_version=sw_version
    )


