def save_report_data(file_path, file_header, processed_data):
    # type: (str, str, List[str]) -> None
    with open(file_path, 'w') as fd:
        fd.write(file_header)

        for data in processed_data:
            fd.write(data)


def build_in_memory_file(file_header, processed_data):
    # type: (str, List[str]) -> str
    in_memory_txt_file = StringIO(newline='\n')
    in_memory_txt_file.write(text_type(file_header))
    for data in processed_data:
        in_memory_txt_file.write(text_type(data))

    return in_memory_txt_file.getvalue()


class BaseSaver(object):
    def __init__(self, data, target_file_path):
        # type: (str, str) -> None
        self.data = data
        self.target_file_path = target_file_path

    def save(self):
        directory_path = os.path.dirname(self.target_file_path)
        if not os.path.exists(directory_path):
            os.makedirs(directory_path)
        self._save()
        LOGGER.info('Saved file {}'.format(self.target_file_path))
        return self.target_file_path

    def _save(self):
        raise NotImplementedError


class TxtSaver(BaseSaver):
    def __init__(self, data, target_file_path):
        super(TxtSaver, self).__init__(data, target_file_path)

    def _save(self):
        with open(self.target_file_path, 'w') as fh:
            fh.write(self.data)


class ZipSaver(BaseSaver):
    def __init__(self, data, target_file_path):
        super(ZipSaver, self).__init__(data, target_file_path)
        self.target_file_path = target_file_path.replace('.txt', '.zip')

    def _save(self):
        in_zip_file_name = os.path.basename(self.target_file_path)
        in_zip_file_name = in_zip_file_name.replace('.zip', '.txt')

        zf = zipfile.ZipFile(self.target_file_path,
                             mode='w',
                             compression=zipfile.ZIP_DEFLATED,
                             )
        try:
            zf.writestr(in_zip_file_name, self.data)
        finally:
            zf.close()


def zip_files(file_names_list, zip_file_path='/home/ute/tti.zip'):
    # type: (List[str], str) -> None
    zf = zipfile.ZipFile(zip_file_path,
                         mode='w',
                         compression=zipfile.ZIP_DEFLATED,
                         )

    try:
        for item in file_names_list:
            arcname = os.path.basename(item)
            zf.write(item, arcname)

    finally:
        zf.close()


