def remove_file(path):
    try:
        subprocess.check_output('sudo rm -f {}'.format(path), shell=True)
        LOGGER.debug('Removed file {}'.format(path))
    except subprocess.CalledProcessError:
        LOGGER.debug('Could not remove file {}'.format(path))
